waves.point_eqs_eel:
flip=flip+1;
flip=if(above(flip,1),0,flip);

xp=sin(sample*6.283);
yp=cos(sample*6.283);

scale1=sin(sample*6.283*3);
scale2=sin(sample*6.283*9);
scale3=sin(sample*6.283*5);
scale=scale1+scale2*0.7+scale3*0.4;
scale=scale*0.5;

xp=xp*scale;
yp=yp*scale;

x1=xp*0.25 +0.5;
y1=yp*0.25*1.333 + 0.5;
x2=0.5+q4;
y2=0.5+q5;
x=x1*flip + x2*(1-flip);
y=y1*flip + y2*(1-flip);

a=flip*0.05;
r=sin(time)*0.5+0.5;
g=sin(time+2.1)*0.5+0.5;
b=sin(time+4.2)*0.5+0.5;

preset.frame_eqs_eel:
decay=0.985;

vol= (bass+mid+treb)*0.55;
vol=vol;


mv_r = 0.5 + 0.4*sin(time*1.324);
mv_g = 0.5 + 0.4*cos(time*1.371);

q1=ypos;
q2=xpos;
wave_a = 0;



zoom=0.9;

musictime=musictime+vol*0.5;
q4=sin(musictime*0.02)*0.3;
q5=sin(musictime*0.01)*0.3;

dx=sin(musictime*0.1)*0.01;
dy=cos(musictime*0.069)*0.01;




monitor=rot;

preset.pixel_eqs_eel:
rd=sqrt( sqr( (x-0.5-q4)*1.7) + sqr( (y-0.5+q5)*1.2 ) );
cx=0.5+q4;
cy=0.5-q5;
zm =-5.5*log(sqrt(2)-rd) -0.24;
zm = max(abs(zm),.99) * sign(zm);
orb=below(rd,0.4);
zm=zm*((1-orb)+rd*rd*rd*1.52) + orb*(1-rd*rd*rd*1.52);
sx=zm;sy=zm;
